CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL CHECK (char_length(full_name) BETWEEN 2 AND 100), phone text NOT NULL CHECK (phone ~ '^\+?[0-9 ()-]{10,20}$'), email text NOT NULL DEFAULT '' CHECK (char_length(email) <= 255), project_type text NOT NULL CHECK (char_length(project_type) BETWEEN 1 AND 100), location text NOT NULL CHECK (char_length(location) BETWEEN 2 AND 200), preferred_styles text[] NOT NULL DEFAULT '{}', selected_services text[] NOT NULL DEFAULT '{}', preferred_rooms text[] NOT NULL DEFAULT '{}', budget text NOT NULL DEFAULT '', timeline text NOT NULL DEFAULT '', message text NOT NULL DEFAULT '' CHECK (char_length(message) <= 3000), consent boolean NOT NULL CHECK (consent = true), status text NOT NULL DEFAULT 'New' CHECK (status IN ('New','Contacted','Consultation Scheduled','In Progress','Completed','Closed')), created_at timestamptz NOT NULL DEFAULT now()); GRANT INSERT ON public.enquiries TO anon, authenticated; GRANT ALL ON public.enquiries TO service_role; ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY; CREATE POLICY "Visitors can submit enquiries" ON public.enquiries FOR INSERT TO anon, authenticated WITH CHECK (consent = true AND status = 'New'); CREATE TABLE public.testimonials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_name text NOT NULL CHECK (char_length(client_name) BETWEEN 2 AND 100), project_type text NOT NULL, rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), review_text text NOT NULL CHECK (char_length(review_text) BETWEEN 10 AND 2000), approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now()); GRANT INSERT ON public.testimonials TO anon, authenticated; GRANT SELECT ON public.testimonials TO anon, authenticated; GRANT ALL ON public.testimonials TO service_role; ALTER TABLE public.testimonials ENABLE ROW LEVEL SECURITY; CREATE POLICY "Submit pending reviews" ON public.testimonials FOR INSERT TO anon, authenticated WITH CHECK (approved = false); CREATE POLICY "Read approved reviews" ON public.testimonials FOR SELECT TO anon, authenticated USING (approved = true);